server_generation = '''namespace SharpLink.Server;\n\ninternal sealed partial class SharpLinkServer\n{\n    private sealed class ServerInterceptorGeneration\n    {\n        private static readonly SharpLinkServerInvocationDelegate Terminal = InvokeTerminalAsync;\n\n        private ServerInterceptorGeneration(\n            ISharpLinkServerInterceptor[] snapshot,\n            SharpLinkServerInvocationDelegate entry)\n        {\n            Snapshot = snapshot;\n            Entry = entry;\n        }\n\n        public ISharpLinkServerInterceptor[] Snapshot { get; }\n        public int Count => Snapshot.Length;\n        public SharpLinkServerInvocationDelegate Entry { get; }\n\n        public static ServerInterceptorGeneration Create(ISharpLinkServerInterceptor[] snapshot)\n        {\n            ArgumentNullException.ThrowIfNull(snapshot);\n            SharpLinkServerInvocationDelegate next = Terminal;\n            for (var index = snapshot.Length - 1; index >= 0; index--)\n            {\n                var node = new ServerInterceptorNode(snapshot[index], next);\n                next = node.InvokeAsync;\n            }\n            return new ServerInterceptorGeneration(snapshot, next);\n        }\n\n        private static async ValueTask InvokeTerminalAsync(SharpLinkServerInvocationContext context)\n        {\n            context.InterceptorTerminalReached = true;\n            var stub = context.InterceptorStub as IRpcStub\n                ?? throw new InvalidOperationException(\"The Server interceptor terminal stub is unavailable.\");\n            var service = context.InterceptorService\n                ?? throw new InvalidOperationException(\"The Server interceptor terminal service is unavailable.\");\n            var generatedBridge = context.InterceptorGeneratedBridge as IRpcGeneratedServerBridge\n                ?? throw new InvalidOperationException(\"The Server interceptor generated bridge is unavailable.\");\n            var output = context.InterceptorOutput as IRpcByteBufferWriter;\n            var timeProvider = context.InterceptorTimeProvider\n                ?? throw new InvalidOperationException(\"The Server interceptor time provider is unavailable.\");\n\n            try\n            {\n                if (output is null)\n                {\n                    await stub.InvokeNoReturnCancellableAsync(\n                        service, generatedBridge, context.InterceptorMethodId, context.RequestId,\n                        context.InterceptorArguments, context.CancellationToken).ConfigureAwait(false);\n                }\n                else\n                {\n                    await stub.InvokeCancellableAsync(\n                        service, generatedBridge, context.InterceptorMethodId, context.RequestId,\n                        context.InterceptorArguments, output, context.CancellationToken).ConfigureAwait(false);\n                }\n                if (context.Status == SharpLinkInvocationStatus.Pending)\n                    context.Status = SharpLinkInvocationStatus.Succeeded;\n            }\n            catch (Exception exception)\n            {\n                RecordInvocationFailure(context, exception);\n                throw;\n            }\n            finally\n            {\n                context.Elapsed = timeProvider.GetElapsedTime(context.InterceptorStarted);\n            }\n        }\n\n        private sealed class ServerInterceptorNode(\n            ISharpLinkServerInterceptor interceptor,\n            SharpLinkServerInvocationDelegate next)\n        {\n            public ValueTask InvokeAsync(SharpLinkServerInvocationContext context)\n            {\n                try\n                {\n                    var generatedBridge = context.InterceptorGeneratedBridge as IRpcGeneratedServerBridge\n                        ?? throw new InvalidOperationException(\"The Server interceptor generated bridge is unavailable.\");\n                    generatedBridge.EnsureUserCodeEntry(context.RequestId);\n                    return interceptor.InvokeAsync(context, next);\n                }\n                catch (Exception exception)\n                {\n                    return ValueTask.FromException(exception);\n                }\n            }\n        }\n    }\n}\n'''
Path('src/SharpLink.Server/SharpLinkServer.InterceptorGeneration.cs').write_text(server_generation)

server = 'src/SharpLink.Server/SharpLinkServer.Interceptors.cs'
old_zero = '''            await new ServerPipelineFacts(\n                interceptors,\n                stub,\n                service,\n                session,\n                generatedBridge,\n                methodId,\n                requestId,\n                ReadOnlySequence<byte>.Empty,\n                output,\n                _runtimeContext.TimeProvider,\n                cancellationToken).InvokeAsync(context).ConfigureAwait(false);'''
new_zero = '''            await InvokeComposedServerInterceptorsAsync(\n                interceptors,\n                stub,\n                service,\n                generatedBridge,\n                methodId,\n                requestId,\n                ReadOnlySequence<byte>.Empty,\n                output,\n                cancellationToken,\n                context).ConfigureAwait(false);'''
replace_once(server, old_zero, new_zero)

old_owned = '''            await new ServerPipelineFacts(\n                interceptors,\n                stub,\n                service,\n                session,\n                generatedBridge,\n                methodId,\n                requestId,\n                ownedArguments,\n                output,\n                _runtimeContext.TimeProvider,\n                cancellationToken).InvokeAsync(context).ConfigureAwait(false);'''
new_owned = '''            await InvokeComposedServerInterceptorsAsync(\n                interceptors,\n                stub,\n                service,\n                generatedBridge,\n                methodId,\n                requestId,\n                ownedArguments,\n                output,\n                cancellationToken,\n                context).ConfigureAwait(false);'''
replace_once(server, old_owned, new_owned)

marker = '''    private static async ValueTask ObserveServerCallAsync(\n        ValueTask invocation,\n        SharpLinkTelemetry.CallScope telemetry)'''
helper = '''    private async ValueTask InvokeComposedServerInterceptorsAsync(\n        ServerInterceptorGeneration interceptors,\n        IRpcStub stub,\n        object service,\n        IRpcGeneratedServerBridge generatedBridge,\n        long methodId,\n        long requestId,\n        ReadOnlySequence<byte> arguments,\n        IRpcByteBufferWriter? output,\n        CancellationToken cancellationToken,\n        SharpLinkServerInvocationContext context)\n    {\n        var timeProvider = _runtimeContext.TimeProvider;\n        context.InterceptorStub = stub;\n        context.InterceptorService = service;\n        context.InterceptorGeneratedBridge = generatedBridge;\n        context.InterceptorMethodId = methodId;\n        context.InterceptorArguments = arguments;\n        context.InterceptorOutput = output;\n        context.InterceptorTimeProvider = timeProvider;\n        context.InterceptorStarted = timeProvider.GetTimestamp();\n        context.InterceptorTerminalReached = false;\n\n        try\n        {\n            await interceptors.Entry(context).ConfigureAwait(false);\n            if (output is not null && !context.InterceptorTerminalReached)\n            {\n                throw new InvalidOperationException(\n                    \"A Server interceptor must invoke its continuation for a response-bearing RPC.\");\n            }\n            if (context.Status == SharpLinkInvocationStatus.Pending)\n                context.Status = SharpLinkInvocationStatus.Succeeded;\n        }\n        catch (Exception exception)\n        {\n            RecordInvocationFailure(context, exception);\n            throw;\n        }\n        finally\n        {\n            context.Elapsed = timeProvider.GetElapsedTime(context.InterceptorStarted);\n            context.InterceptorStub = null;\n            context.InterceptorService = null;\n            context.InterceptorGeneratedBridge = null;\n            context.InterceptorArguments = default;\n            context.InterceptorOutput = null;\n            context.InterceptorTimeProvider = null;\n        }\n    }\n\n''' + marker
replace_once(server, marker, helper)

print('issue 406 option-2 server context candidate patched')
